insert into public.templates (id, key, subject, body_html, version, active, created_at, updated_at)
values
  ('00000000-0000-0000-0000-000000007001', 'quote_email', 'Your Rovos Rail Quote - {{jobNumber}}', '<p>Dear {{customerName}},</p><p>Please find attached your personalised quotation for the <strong>{{direction}}</strong> journey departing on <strong>{{departureDate}}</strong>.</p><p>This quote is valid until <strong>{{validityDate}}</strong>.</p><p>Total: <strong>R{{total}}</strong></p><p>Kind regards,<br/>Luxus Travel &amp; Tours</p>', 2, true, '2025-08-12T08:00:00Z', '2025-08-12T08:00:00Z'),
  ('00000000-0000-0000-0000-000000007002', 'follow_up', 'Following up on your Rovos Rail enquiry - {{jobNumber}}', '<p>Dear {{customerName}},</p><p>We are following up on the quotation sent on <strong>{{lastSentDate}}</strong> for your Rovos Rail journey.</p><p>Please let us know if you would like any amendments.</p><p>Warm regards,<br/>Luxus Travel &amp; Tours</p>', 1, true, '2025-08-12T08:00:00Z', '2025-08-12T08:00:00Z'),
  ('00000000-0000-0000-0000-000000007003', 'deposit_request', 'Deposit Request - {{jobNumber}}', '<p>Dear {{customerName}},</p><p>Thank you for confirming your Rovos Rail reservation. To secure your booking, a deposit of <strong>R{{depositAmount}}</strong> is required.</p><p>Kind regards,<br/>Luxus Travel &amp; Tours</p>', 1, true, '2025-08-12T08:00:00Z', '2025-08-12T08:00:00Z'),
  ('00000000-0000-0000-0000-000000007004', 'voucher_email', 'Your Travel Voucher - {{jobNumber}}', '<p>Dear {{customerName}},</p><p>Please find attached your travel voucher for the <strong>{{direction}}</strong> journey.</p><p>For any queries, please contact your consultant. Safe travels!</p>', 1, true, '2025-08-12T08:00:00Z', '2025-08-12T08:00:00Z');
